import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n = int(sys.stdin.readline())
        a = list(map(int, sys.stdin.readline().split()))
        max_coins = 0
        for num in a:
            if num == 0:
                coins = 0
            else:
                coins = num // 3 + (num % 3 == 1) * 2 + (num % 3 == 2) * 1
                coins = min(coins, num // 2 + num % 2, num)
            max_coins = max(max_coins, coins)
        print(max_coins)

solve()
